#!/usr/bin/env bun
// SPDX-License-Identifier: FSL-1.1-ALv2
/**
 * I7: adding a locale must be FILE-ONLY (no hand code edit). This generator
 * scans packages/shared/src/i18n/locales/<locale>/<ns>.json and (re)writes the
 * single generated module `locales/_generated.ts` that `dictionaries.ts` and
 * `locales.ts` consume. Dropping a new `locales/<x>/*.json` directory and
 * (re)running this — wired into `predev`/`prebuild` so it is automatic — makes
 * the locale shipped + selectable with zero hand-written code changes.
 *
 * `--check` exits non-zero if the on-disk generated file is stale (CI guard),
 * mirroring the existing i18n:fr:check pattern.
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const LOCALES_DIR = join(import.meta.dir, "..", "packages", "shared", "src", "i18n", "locales")
const OUT = join(LOCALES_DIR, "_generated.ts")

function listDirs(p: string): string[] {
  return readdirSync(p)
    .filter((n) => !n.startsWith("_") && !n.startsWith("."))
    .filter((n) => statSync(join(p, n)).isDirectory())
    .sort()
}

function listNamespaces(localeDir: string): string[] {
  return readdirSync(localeDir)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.slice(0, -".json".length))
    .sort()
}

function ident(locale: string, ns: string): string {
  const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)
  return `${locale.replace(/[^a-zA-Z0-9]/g, "_")}_${cap(ns).replace(/[^a-zA-Z0-9]/g, "_")}`
}

function build(): string {
  const locales = listDirs(LOCALES_DIR)
  if (!locales.includes("en")) {
    throw new Error("i18n-gen: 'en' locale directory is required (fallback source)")
  }
  const imports: string[] = []
  const dictBlocks: string[] = []
  for (const locale of locales) {
    const nsList = listNamespaces(join(LOCALES_DIR, locale))
    const entries: string[] = []
    for (const ns of nsList) {
      const id = ident(locale, ns)
      imports.push(`import ${id} from "./${locale}/${ns}.json"`)
      entries.push(`    ${JSON.stringify(ns)}: ${id} as LocaleDict,`)
    }
    dictBlocks.push(`  ${JSON.stringify(locale)}: {\n${entries.join("\n")}\n  },`)
  }
  const localeList = locales.map((l) => JSON.stringify(l)).join(", ")
  return `// AUTO-GENERATED by scripts/i18n-gen-dictionaries.ts — DO NOT EDIT.
// Regenerate: \`bun run i18n:gen\` (runs automatically via predev/prebuild).
// Adding a locale is FILE-ONLY: drop locales/<x>/*.json and this regenerates.
import type { LocaleDict } from "../dictionaries"

${imports.join("\n")}

export const GENERATED_LOCALES = [${localeList}] as const

export const GENERATED_DICTIONARIES: Record<
  (typeof GENERATED_LOCALES)[number],
  Record<string, LocaleDict>
> = {
${dictBlocks.join("\n")}
}
`
}

// The repo's formatter is the authority on what this file looks like: emitting
// anything else makes `i18n:gen:check` report a stale file forever (biome
// rewrites the quoting the moment anyone runs `check --write`), and a check
// nobody can make green is a check nobody reads.
function formatWithBiome(source: string): string {
  const biome = join(import.meta.dir, "..", "node_modules", ".bin", "biome")
  const result = Bun.spawnSync([biome, "format", `--stdin-file-path=${OUT}`], {
    cwd: join(import.meta.dir, ".."),
    stdin: Buffer.from(source),
    stdout: "pipe",
    stderr: "pipe",
  })
  if (result.exitCode !== 0) {
    throw new Error(`i18n-gen: biome format failed: ${result.stderr.toString()}`)
  }
  return result.stdout.toString()
}

const generated = formatWithBiome(build())
const isCheck = process.argv.includes("--check")
let current = ""
try {
  current = readFileSync(OUT, "utf8")
} catch {
  current = ""
}

if (isCheck) {
  if (current !== generated) {
    console.error("i18n-gen: locales/_generated.ts is STALE. Run `bun run i18n:gen` and commit.")
    process.exit(1)
  }
  console.log("i18n-gen: _generated.ts is up to date.")
} else {
  if (current !== generated) {
    writeFileSync(OUT, generated)
    console.log(`i18n-gen: wrote ${OUT}`)
  } else {
    console.log("i18n-gen: _generated.ts already up to date.")
  }
}
